// === Tab: mySketch ===
// max/min amount of particles to create in each iteration
let PK_NEW_AMOUNT_MAX = 15;
let PK_NEW_AMOUNT_MIN = 10;

// initial horizontal offset for new particles
let PK_INIT_OFFSET_X_MIN = -7;
let PK_INIT_OFFSET_X_MAX =  7;

// initial vertical offset for new particles
let PK_INIT_OFFSET_Y_MIN = -10;
let PK_INIT_OFFSET_Y_MAX =   4;

// initial horizontal speed for new particles
let PK_INIT_SPEED_X_MIN = -0.2;
let PK_INIT_SPEED_X_MAX =  0.2;

// initial vertical speed for new particles
let PK_INIT_SPEED_Y_MIN = -1.5;
let PK_INIT_SPEED_Y_MAX = -1.0;

// max/min initial size of a particle
let PK_INIT_SIZE_MAX = 11;
let PK_INIT_SIZE_MIN =  9;

// particle size change per iteration
let PK_SIZE_CHANGE = -0.1;

// min size of a particle at the end of its life
let PK_SIZE_MIN = 1;

// horizontal/vertical acceleration for all particles
let PK_ACCEL_Y = -0.01;
let PK_ACCEL_X =  0;

// size below which the particles turn gray
let PK_GRAY_SIZE = 8;


ArrayList<Particle> particles;

// utility object to draw faster circles (i.e. only ten sides)
// so that the sketch runs faster with many particles
let fastCircle = new FastCircle(10);


function setup() {
  createCanvas(400, 400);
  particles = new ArrayList<Particle>();
  textSize(16);
}


function draw() {
  background(0);

	let emmiterX, emmiterY;

	// determine the location for new particles
	// if the mouse is pressed, use the mouse position
	// otherwise use an elliptical motion
	if (mousePressed) {
		emmiterX = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
		emmiterY = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));
	}
	else {
		emmiterX = width/2  + sin(millis()/300.0) * width/3;
		emmiterY = height*2/3;
	} 

	// create a bunch of new particles every frame
	createNewParticles(emmiterX, emmiterY);

  // go through the list of particles
  // (we trravel backwards to ensure proper traversal when removing)
  for (i = particles.size()-1; i >= 0; i--) {

    let p = particles.get(i);  // get a particle

    p.updateParticle();             // draw the particle
    if (p.size <= PK_SIZE_MIN) {    // check if the particle is "dead"
      particles.remove(i);          // if so, remove it from the list
    }
    p.drawParticle();               // draw the particle
  }

  // display text with the number of particles and framerate
  fill(255);
  text("Particle count: " + particles.size() + "\nFramerate: " + int(frameRate), 10, 40);
}


// create new particles at the specified coordinates
function createNewParticles(x, y) {
  // determine how many new particles to create
  let nParticles = int(random)(PK_NEW_AMOUNT_MIN, PK_NEW_AMOUNT_MAX);  

  for (i = 0; i < nParticles; i++) {
    var p = new Particle(x, y);     // create a particle
    particles.add(p);                    // add the particle to the list
  }
}


class Particle {
  x;         // the x coordinate of the particle
  y;         // the y coordinate of the particle
  speedX;    // the horizontal speed of the particle
  speedY;    // the vertical speed of the particle
  size;      // the size of the particle
  col;       // the let of the particle

  constructor(posX, posY) {
    // set random characteristics for new particles
    randomize(posX, posY);
  }

  function randomize(posX, posY) {
    x = posX + random(PK_INIT_OFFSET_X_MIN, PK_INIT_OFFSET_X_MAX);
    y = posY + random(PK_INIT_OFFSET_Y_MIN, PK_INIT_OFFSET_X_MAX);
    speedX = random(PK_INIT_SPEED_X_MIN, PK_INIT_SPEED_X_MAX);  
    speedY = random(PK_INIT_SPEED_Y_MIN, PK_INIT_SPEED_Y_MAX);
    size   = random(PK_INIT_SIZE_MIN, PK_INIT_SIZE_MAX);
  }

  function updateParticle() {
    // update the acceleration
    speedX += PK_ACCEL_X;
    speedY += PK_ACCEL_Y;
    // update the speed
    y += speedY;
    x += speedX;
    // update the size
    size += PK_SIZE_CHANGE;
    size = max(size, PK_SIZE_MIN);
    // determine the let of the particle
    if (size > PK_GRAY_SIZE) {
      let red   = map(size, PK_INIT_SIZE_MAX, PK_GRAY_SIZE, 255, 100);
      let green = map(size, PK_INIT_SIZE_MAX, PK_GRAY_SIZE, 150, 100);
      let blue  = map(size, PK_INIT_SIZE_MAX, PK_GRAY_SIZE, 0,   100);
      col = color(red, green, blue);
    }
    else {
      col = color(map(size, PK_GRAY_SIZE, PK_SIZE_MIN, 100, 50));
    }
  }

  function drawParticle() {
    noStroke();
    fill(col);
    pushMatrix();
    translate(x,y);
    fastCircle.draw(size);
    popMatrix();
  }  
}


class FastCircle {
  float [] vertexesX;
  float [] vertexesY;
  numSides;

  constructor(numSides) {
    setNumSides(numSides);
  }

  function setNumSides(numSides) {
    this.numSides = numSides;
    vertexesX = new float [numSides];
    vertexesY = new float [numSides];
    for (i = 0; i < numSides; i++) {
      let angle = i * (TWO_PI/float(numSides));
      vertexesX[i] = cos(angle);
      vertexesY[i] = sin(angle);
    }
  }

  function draw(radius) {
    beginShape();
    for (i = 0; i < numSides; i++) {
      vertex(vertexesX[i]*radius, vertexesY[i]*radius); 
    }
    endShape(CLOSE);
  }
}

